mapper.select:
SELECT
    id,
    email AS userId,
    record_date AS recordDate,
    meal_type AS mealType
FROM diet_records
WHERE email = #{userId}
  AND DATE(record_date) = #{recordDate}
ORDER BY record_date DESC, id DESC
LIMIT #{limit} OFFSET #{offset}

mapper.insert:
INSERT INTO diet_records (
    email,
    record_date,
    meal_type
) VALUES (
    #{userId},
    #{recordDate},
    #{mealType}
)

mapper.update:
UPDATE diet_records
SET
    record_date = #{request.recordDate},
    meal_type   = #{request.mealType}
WHERE id = #{id}

mapper.delete:
DELETE FROM diet_records
WHERE id = #{id}
  AND email = #{userId}
